{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-849970906cdc526a","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Epic-size overage triggers: when the decomposition summary itself\n28\t     acknowledges an epic above the ~2-week size guideline, the summary must\n29\t     also carry a re-split trigger — the concrete planning condition under\n30\t     which the epic should be re-split. An overage left as a bare \"noted for\n31\t     planning awareness\" note is an unresolved defect the review re-docks;\n32\t     an overage with a trigger is a managed trade-off.\n33\t\n34\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n35\t\n36\tUsage:\n37\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n38\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n39\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n40\t\"\"\"\n41\t\n42\timport argparse\n43\timport os\n44\timport re\n45\timport sys\n46\t\n47\timport yaml\n48\t\n49\tSECTIONS = [(\"Description\", (\"description\",)),\n50\t            (\"Scope\", (\"scope\",)),\n51\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n52\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n53\t\n54\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n55\t\n56\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n57\t           \"repo-onboarding\")\n58\t\n59\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n60\t# way) — parity with the implementation_type_rules judge.\n61\tPARALLEL_PAIRS = {\n62\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n63\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n64\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n65\t}\n66\t\n67\t# Check 6 — a sentence acknowledging an epic over the size guideline\n68\t# (\"above/exceeds/over ... guideline/2-week/sprint\"), excluding negated\n69\t# affirmations (\"no epic exceeds\", \"stays within the guideline\").\n70\tOVER_PAT = re.compile(\n71\t    r'\\b(above|exceeds?|exceeding|over|larger than|bigger than)\\b[^.\\n]{0,120}'\n72\t    r'\\b(2-week|two-week|guideline|sprint|epic[- ]size|size guideline)\\b',\n73\t    re.I)\n74\tNEG_PAT = re.compile(\n75\t    r'\\b(no epic|none|within|under|not exceed|doesn?t exceed|'\n76\t    r'do(es)? not exceed|stays? within|below|smaller|fewer than|at most)\\b',\n77\t    re.I)\n78\t# A re-split trigger: a conditional that names the planning condition under\n79\t# which the epic should be re-split.\n80\tTRIG_PAT = re.compile(\n81\t    r're-split|resplit|split[^.\\n]{0,80}\\bif\\b|\\bif\\b[^.\\n]{0,100}'\n82\t    r'(exceed|finds?|grow|outgrow|materially|more (sites|files|calls|than))|'\n83\t    r'trigger', re.I)\n84\t\n85\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n86\t\n87\t\n88\tdef read_frontmatter(path):\n89\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n90\t    with open(path, encoding=\"utf-8\") as f:\n91\t        content = f.read()\n92\t    m = FRONTMATTER_RE.match(content)\n93\t    if not m:\n94\t        return {}, content\n95\t    try:\n96\t        data = yaml.safe_load(m.group(1))\n97\t    except yaml.YAMLError:\n98\t        return {}, content\n99\t    if not isinstance(data, dict):\n100\t        return {}, content\n101\t    return data, content[m.end():]\n102\t\n103\t\n104\tdef body_headings(body):\n105\t    heads = []\n106\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n107\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n108\t    return heads\n109\t\n110\t\n111\tdef load_epics(artifacts_dir, strat_id):\n112\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n113\t\n114\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n115\t    \"\"\"\n116\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n117\t    if not os.path.isdir(task_dir):\n118\t        return {}\n119\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n120\t    epics = {}\n121\t    for name in sorted(os.listdir(task_dir)):\n122\t        m = pat.match(name)\n123\t        if not m:\n124\t            continue\n125\t        path = os.path.join(task_dir, name)\n126\t        fm, body = read_frontmatter(path)\n127\t        epics[name[:-3]] = (path, fm, body)\n128\t    return epics\n129\t\n130\t\n131\tdef dependency_closure(start_key, deps):\n132\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n133\t    seen, stack = set(), list(deps.get(start_key, []))\n134\t    while stack:\n135\t        n = stack.pop()\n136\t        if n in seen or n not in deps:\n137\t            continue\n138\t        seen.add(n)\n139\t        stack.extend(deps[n])\n140\t    return seen\n141\t\n142\t\n143\tdef check_oversize_trigger(artifacts_dir, strat_id):\n144\t    \"\"\"Check 6: a summary that acknowledges an epic above the size guideline\n145\t    must carry a re-split trigger somewhere in the summary. Judge parity: the\n146\t    dq grader docks an acknowledged overage left as a bare planning note and\n147\t    scores full marks when the overage carries a conditional re-split\n148\t    trigger. Returns a list of violation strings.\"\"\"\n149\t    path = os.path.join(artifacts_dir, \"epic-tasks\",\n150\t                        strat_id + \"-decomposition.md\")\n151\t    if not os.path.isfile(path):\n152\t        return []\n153\t    with open(path, encoding=\"utf-8\") as f:\n154\t        summary = f.read()\n155\t    sentences = re.split(r'(?<=[.!?])\\s+|\\n', summary)\n156\t    overage = [s.strip() for s in sentences\n157\t               if OVER_PAT.search(s) and not NEG_PAT.search(s)]\n158\t    if overage and not TRIG_PAT.search(summary):\n159\t        return [\"summary acknowledges an epic above the size guideline \"\n160\t                \"(\\\"...%s...\\\") with no re-split trigger — record the \"\n161\t                \"concrete planning condition under which the epic should be \"\n162\t                \"re-split (e.g. \\\"re-split along sub-system lines if the \"\n163\t                \"audit finds materially more call sites than the \"\n164\t                \"estimate\\\") in the same Health Warning\"\n165\t                % overage[0][:160]]\n166\t    return []\n167\t\n168\t\n169\tdef check(strat_id, artifacts_dir, components_path):\n170\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n171\t    probs = []\n172\t    epics = load_epics(artifacts_dir, strat_id)\n173\t    if not epics:\n174\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n175\t                % (strat_id, artifacts_dir)]\n176\t\n177\t    valid_components = set()\n178\t    if os.path.isfile(components_path):\n179\t        with open(components_path, encoding=\"utf-8\") as f:\n180\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n181\t    if not valid_components:\n182\t        probs.append(\"cannot read canonical component list %s — verify the \"\n183\t                     \"path before trusting component names\" % components_path)\n184\t\n185\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n186\t    for key, (path, fm, body) in epics.items():\n187\t        name = key + \".md\"\n188\t        # 1. body sections (contract parity with the artifact judge)\n189\t        heads = body_headings(body)\n190\t        for want, aliases in SECTIONS:\n191\t            if not any(a in h for h in heads for a in aliases):\n192\t                probs.append(\"%s: body missing '%s' section (required \"\n193\t                             \"sections: Description, Scope, Acceptance \"\n194\t                             \"Criteria, HLR Traceability)\" % (name, want))\n195\t        # 2. component vocabulary\n196\t        comp = fm.get(\"component\")\n197\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n198\t                and comp.strip() not in valid_components:\n199\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n200\t                         \"canonical name (submit.py strips unknown names)\"\n201\t                         % (name, comp.strip(), components_path))\n202\t        # collect graph facts\n203\t        dl = fm.get(\"dependencies\")\n204\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n205\t            if isinstance(dl, list) else []\n206\t        is_branch[key] = \"BRANCH-\" in key\n207\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n208\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n209\t        it = fm.get(\"implementation_type\")\n210\t        itype[key] = it if it in IT_ENUM else None\n211\t        prio[key] = fm.get(\"priority\")\n212\t\n213\t    def kind(key):\n214\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n215\t        that is not type Implementation is never a parallel-rule party; an\n216\t        Implementation epic's kind is its implementation_type when that is a\n217\t        known label, else 'general'.\"\"\"\n218\t        if not is_impl[key]:\n219\t            return \"non-implementation\"\n220\t        return itype[key] or \"general\"\n221\t\n222\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n223\t    universe = [k for k in epics\n224\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n225\t    for k in sorted(epics):\n226\t        if not is_docs[k]:\n227\t            continue\n228\t        cl = dependency_closure(k, deps)\n229\t        missing = sorted(e for e in universe if e != k and e not in cl)\n230\t        if missing:\n231\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n232\t                         \"Implementation epic — add %s to its dependency chain\"\n233\t                         % (k, \", \".join(missing)))\n234\t\n235\t    # 4. Priority inheritance — enablers of P0 work must be P0\n236\t    for k in sorted(epics):\n237\t        if is_branch[k] or is_docs[k]:\n238\t            continue\n239\t        if prio.get(k) != \"P0\":\n240\t            continue\n241\t        # every main-plan, non-docs epic in k's closure enables P0 work\n242\t        cl = dependency_closure(k, deps)\n243\t        for t in sorted(cl):\n244\t            if is_branch[t] or is_docs[t]:\n245\t                continue\n246\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n247\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n248\t                             \"but is %s — raise it to P0 or restructure\"\n249\t                             % (t, prio.get(t), k, prio.get(t)))\n250\t\n251\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n252\t    #    pairs carry no dependencies edge in either direction (direct edges\n253\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n254\t    #    them; dependencies naming epics with no file cannot be judged).\n255\t    for k in sorted(epics):\n256\t        if kind(k) == \"docs-authoring\":\n257\t            continue\n258\t        for t in deps[k]:\n259\t            if t not in epics:\n260\t                continue\n261\t            pair = frozenset((kind(t), kind(k)))\n262\t            rule = PARALLEL_PAIRS.get(pair)\n263\t            if rule:\n264\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n265\t                             \"parallel; remove the dependencies edge and \"\n266\t                             \"express any coupling as an AC gate on the \"\n267\t                             \"dependent epic\"\n268\t                             % (rule, t, kind(t), k, kind(k)))\n269\t\n270\t    # 6. Epic-size overage triggers — an acknowledged above-guideline epic\n271\t    #    must carry a re-split trigger in the summary.\n272\t    probs.extend(check_oversize_trigger(artifacts_dir, strat_id))\n273\t    return probs\n274\t\n275\t\n276\t# ─── self-check ───────────────────────────────────────────────────────────────\n277\t\n278\tdef _self_check():\n279\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n280\t    import shutil\n281\t    import tempfile\n282\t\n283\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n284\t    try:\n285\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n286\t        os.makedirs(art)\n287\t        comp = os.path.join(tmp, \"components.txt\")\n288\t        with open(comp, \"w\") as f:\n289\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n290\t\n291\t        def write(name, fm, body):\n292\t            with open(os.path.join(art, name), \"w\") as f:\n293\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n294\t\n295\t        def write_raw(name, content):\n296\t            with open(os.path.join(art, name), \"w\") as f:\n297\t                f.write(content)\n298\t\n299\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n300\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n301\t        write(\"RHAISTRAT-9001-E001.md\",\n302\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n303\t              \"dependencies: []\\n\", good_body)\n304\t        write(\"RHAISTRAT-9001-E002.md\",\n305\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n306\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n307\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n308\t              good_body)\n309\t        # a konflux-onboarding epic parallel to the general epic (no edge\n310\t        # either way) is the Rule 10-compliant shape — must not be flagged\n311\t        write(\"RHAISTRAT-9001-E003.md\",\n312\t              \"component: Dashboard\\ntype: Implementation\\n\"\n313\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n314\t              \"dependencies: [